<?php namespace App\Policies; use App\Models\{User,Pet}; class PetPolicy { public function view(User $u,Pet $p):bool{return $p->owner_id===$u->id || $u->role==='admin' || $u->familyOwners()->where('status','accepted')->where('permissions','manage')->where('owner_id',$p->owner_id)->exists();} public function update(User $u,Pet $p):bool{return $this->view($u,$p);} public function delete(User $u,Pet $p):bool{return $p->owner_id===$u->id || $u->role==='admin';} }